import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';

// New letter-based thumbnail component
const LetterThumbnail = ({ title, category, onClick }) => {
  const { theme } = useTheme();
  const firstLetter = title?.charAt(0)?.toUpperCase() || '?';
  
  // Different colors based on the first letter with more vibrant gradients
  const getColorClass = (letter) => {
    const colors = [
      'from-blue-500 via-blue-600 to-indigo-700', // A-E
      'from-purple-500 via-purple-600 to-violet-700', // F-J
      'from-emerald-500 via-green-600 to-teal-700', // K-O
      'from-red-500 via-rose-600 to-pink-700', // P-T
      'from-amber-500 via-yellow-600 to-orange-700', // U-Z
      'from-slate-500 via-gray-600 to-zinc-700' // others
    ];
    
    const code = letter.charCodeAt(0);
    if (code >= 65 && code <= 69) return colors[0];
    if (code >= 70 && code <= 74) return colors[1];
    if (code >= 75 && code <= 79) return colors[2];
    if (code >= 80 && code <= 84) return colors[3];
    if (code >= 85 && code <= 90) return colors[4];
    return colors[5];
  };
  
  const gradientClass = getColorClass(firstLetter);
  
  return (
    <div 
      className="h-44 relative overflow-hidden cursor-pointer group"
      onClick={onClick}
    >
      {/* Book spine effect */}
      <div className="absolute left-0 top-0 bottom-0 w-[8px] bg-black/20 z-10"></div>
      
      {/* Book cover with gradient */}
      <div className={`w-full h-full flex items-center justify-center bg-gradient-to-br ${gradientClass} relative overflow-hidden`}>
        {/* Background pattern */}
        <div className="absolute inset-0 opacity-10" 
          style={{
            backgroundImage: 'radial-gradient(circle, rgba(255,255,255,0.2) 2px, transparent 2px)',
            backgroundSize: '20px 20px'
          }}
        ></div>
        
        {/* Book edge shadow */}
        <div className="absolute right-0 top-0 bottom-0 w-2 bg-black/10"></div>
        <div className="absolute bottom-0 left-0 right-0 h-2 bg-black/10"></div>
        
        {/* Realistic shine effect */}
        <div className="absolute inset-0 bg-gradient-to-br from-white/30 via-transparent to-transparent opacity-0 group-hover:opacity-20 transition-opacity duration-300"></div>
        
        {/* Letter with shadow */}
        <div className="transform group-hover:scale-110 transition-transform duration-300 relative">
          <span className="text-white text-7xl font-bold" style={{ 
            textShadow: '0 2px 10px rgba(0,0,0,0.3)',
            letterSpacing: '-1px'
          }}>{firstLetter}</span>
        </div>
      </div>
      
      {/* Category Badge */}
      <div className="absolute top-3 right-3 z-10">
        <span className={`text-xs font-medium px-2.5 py-1 rounded-full ${
          theme === 'dark' 
            ? 'bg-blue-900/70 text-blue-100 backdrop-blur-sm' 
            : 'bg-blue-100/80 text-blue-800 backdrop-blur-sm'
        } shadow-sm`}>
          {category}
        </span>
      </div>
      
      {/* Book edge highlighting on hover */}
      <div className="absolute left-0 top-0 bottom-0 w-1 bg-white/40 opacity-0 group-hover:opacity-100 transition-opacity duration-300 z-20"></div>
    </div>
  );
};

const BookListWithThumbnails = ({ onBookClick }) => {
  const [books, setBooks] = useState([]);
  const [filteredBooks, setFilteredBooks] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const [currentCategory, setCurrentCategory] = useState('All');
  const [categories, setCategories] = useState(['All']);
  const [searchTerm, setSearchTerm] = useState('');
  const { theme } = useTheme();

  useEffect(() => {
    const loadBooks = async () => {
      try {
        setIsLoading(true);
        
        // Get books from the public/books folder
        const bookFiles = [
          "Simple_Test.pdf",
          "test_thumbnail.pdf",
          "Personal Jokes in Aristophanes FS Halliwell, Worcester College D Phil The material of this thesis - PDF Room.pdf",
          "Yo Mama Jokes EncyclopediaThe Worlds Funniest Yo Momma Jokes! - PDF Room.pdf",
          "The Funniest Five Thousand Jokes - PDF Room.pdf",
          "The Ginormous Book of Dirty Jokes_ Over 1,000 Sick, Filthy and X-Rated Jokes - PDF Room.pdf",
          "The Best Joke Book Period_ Hundreds of the Funniest, Silliest, Most Ridiculous Jokes Ever - PDF Room.pdf",
          "The Serious Guide to Joke Writing_ How To Say Something Funny About Anything - PDF Room.pdf",
          "Batman_ The Killing Joke - PDF Room.pdf",
          "Manga Comics_ the-breaker-new-waves-4 - PDF Room.pdf"
        ];
        
        // Create book objects from filenames
        const bookData = bookFiles.map((filename, index) => {
          // Extract a reasonable title from the filename
          let title = filename.replace('.pdf', '');
          
          // Remove " - PDF Room" if it exists
          title = title.replace(' - PDF Room', '');
          
          // Determine category based on content
          let category = 'Book';
          if (title.includes('Joke') || title.includes('Jokes') || title.includes('Funny')) {
            category = 'Humor';
          } else if (title.includes('Comics') || title.includes('Manga') || title.includes('Batman')) {
            category = 'Comics';
          } else if (title.includes('College') || title.includes('thesis')) {
            category = 'Academic';
          } else if (title.includes('Test') || title.includes('Simple')) {
            category = 'Test';
          }
          
          // Extract author if possible
          let author = 'Unknown';
          if (title.includes('FS Halliwell')) {
            author = 'FS Halliwell';
            title = 'Personal Jokes in Aristophanes';
          } else {
            // For other books, try to extract author before any underscore or special character
            const parts = title.split('_');
            if (parts.length > 1) {
              author = parts[1].trim();
              title = parts[0].trim();
            }
          }
          
          // Create description
          const description = `A ${category.toLowerCase()} book titled "${title}" by ${author}.`;
          
          return {
            id: index + 1,
            title: title,
            filename: filename,
            author: author,
            description: description,
            category: category,
            addedDate: new Date(Date.now() - Math.random() * 10000000000).toISOString().split('T')[0]
          };
        });
        
        // Get unique categories
        const uniqueCategories = [...new Set(bookData.map(book => book.category))];
        setCategories(['All', ...uniqueCategories]);
        
        // Create paths for the books
        const publicPath = process.env.PUBLIC_URL || '';
        
        // Map through books and create the local file path for each
        const booksWithPaths = bookData.map(book => {
          // Create URL that points directly to the PDF file in public folder
          const bookPath = `${publicPath}/books/${book.filename}`;
          
          return {
            ...book,
            path: bookPath
          };
        });
        
        console.log('Books with paths:', booksWithPaths);
        
        setBooks(booksWithPaths);
        setFilteredBooks(booksWithPaths);
        setIsLoading(false);
      } catch (error) {
        console.error("Error loading books:", error);
        setError("Failed to load books. Please try again later.");
        setIsLoading(false);
      }
    };

    loadBooks();
  }, []);

  // Filter books when category or search term changes
  useEffect(() => {
    let filtered = books;
    
    // Apply category filter
    if (currentCategory !== 'All') {
      filtered = filtered.filter(book => book.category === currentCategory);
    }
    
    // Apply search filter if search term exists
    if (searchTerm.trim()) {
      const term = searchTerm.toLowerCase().trim();
      filtered = filtered.filter(book => 
        book.title.toLowerCase().includes(term) || 
        book.author.toLowerCase().includes(term) ||
        book.description.toLowerCase().includes(term)
      );
    }
    
    setFilteredBooks(filtered);
  }, [books, currentCategory, searchTerm]);

  // Handle book click with additional error checking
  const handleBookClick = (book) => {
    try {
      console.log("Book selected:", book);
      
      if (!book?.path) {
        console.error("Book path is missing", book);
        return;
      }
      
      // Call the passed in click handler with the book data
      if (onBookClick && typeof onBookClick === 'function') {
        onBookClick(book);
      } else {
        console.error("onBookClick is not a function");
      }
    } catch (error) {
      console.error("Error in handleBookClick:", error);
    }
  };

  return (
    <div className="book-list-container">
      {/* Filters & Search */}
      <div className="filters mb-6">
        <div className="flex flex-col md:flex-row gap-4 justify-between items-start md:items-center">
          {/* Search Bar */}
          <div className="search-container relative w-full md:w-auto">
            <input
              type="text"
              placeholder="Search books..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className={`py-2.5 px-4 pr-10 w-full md:w-72 rounded-lg ${
                theme === 'dark' 
                  ? 'bg-gray-800/80 text-white border border-gray-700/70 focus:border-blue-500' 
                  : 'bg-white/90 text-gray-800 border border-gray-300/70 focus:border-blue-500'
              } focus:outline-none focus:ring-2 focus:ring-blue-500/50 shadow-sm backdrop-blur-sm`}
            />
            <span className="absolute right-3 top-3 text-gray-400">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </span>
          </div>
          
          {/* Category Pills */}
          <div className="categories-container flex flex-wrap gap-2 w-full md:w-auto">
            {categories.map(category => (
              <button
                key={category}
                onClick={() => setCurrentCategory(category)}
                className={`px-3.5 py-2 rounded-full text-sm font-medium transition-all duration-200 ${
                  currentCategory === category
                    ? 'bg-blue-600 text-white shadow-md shadow-blue-600/20'
                    : theme === 'dark'
                      ? 'bg-gray-800/80 text-gray-300 hover:bg-gray-700/80 border border-gray-700/70 hover:border-gray-600'
                      : 'bg-gray-200/90 text-gray-800 hover:bg-gray-300/90 border border-gray-300/70 hover:border-gray-400'
                } backdrop-blur-sm`}
              >
                {category}
              </button>
            ))}
          </div>
        </div>
      </div>
      
      {/* Error Message */}
      {error && (
        <div className={`mb-6 p-4 rounded-lg ${theme === 'dark' ? 'bg-red-900/30 text-red-200' : 'bg-red-100 text-red-800'}`}>
          <p className="font-medium">{error}</p>
          <p className="text-sm mt-1 opacity-80">Try refreshing the page or check your connection.</p>
        </div>
      )}
      
      {/* Loading State */}
      {isLoading ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
          {[...Array(8)].map((_, index) => (
            <div 
              key={`skeleton-${index}`} 
              className={`rounded-xl overflow-hidden border ${
                theme === 'dark' ? 'bg-gray-800/50 border-gray-700/70' : 'bg-gray-100/50 border-gray-200/70'
              } animate-pulse h-72 shadow-md`}
            >
              <div className={`h-44 ${theme === 'dark' ? 'bg-gray-700' : 'bg-gray-300'}`}></div>
              <div className="p-4 space-y-3">
                <div className={`h-4 ${theme === 'dark' ? 'bg-gray-700' : 'bg-gray-300'} rounded w-3/4`}></div>
                <div className={`h-3 ${theme === 'dark' ? 'bg-gray-700' : 'bg-gray-300'} rounded w-1/2`}></div>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <>
          {/* Books Grid */}
          <AnimatePresence mode="wait">
            {filteredBooks.length > 0 ? (
              <motion.div 
                key="book-grid"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6"
              >
                {filteredBooks.map(book => (
                  <motion.div 
                    key={book.id}
                    whileHover={{ y: -8, boxShadow: theme === 'dark' ? '0 10px 30px rgba(0, 0, 0, 0.4)' : '0 10px 30px rgba(0, 0, 0, 0.15)' }}
                    initial={{ scale: 0.95, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    transition={{ duration: 0.3 }}
                    className={`book-card rounded-xl overflow-hidden border ${
                      theme === 'dark' ? 'bg-gray-800/70 border-gray-700/70' : 'bg-white/90 border-gray-200/70'
                    } shadow-md hover:shadow-xl transition-all duration-300 cursor-pointer backdrop-blur-sm`}
                    onClick={() => handleBookClick(book)}
                  >
                    {/* Using letter thumbnail instead of PDF rendering */}
                    <LetterThumbnail
                      title={book.title}
                      category={book.category}
                      onClick={() => handleBookClick(book)}
                    />
                    
                    <div className="p-4">
                      <h3 className={`font-semibold text-lg mb-1 line-clamp-1 ${
                        theme === 'dark' ? 'text-white' : 'text-gray-900'
                      }`}>
                        {book.title}
                      </h3>
                      
                      <p className={`text-sm mb-2 ${
                        theme === 'dark' ? 'text-gray-400' : 'text-gray-600'
                      }`}>
                        by {book.author}
                      </p>
                      
                      <p className={`text-sm line-clamp-2 ${
                        theme === 'dark' ? 'text-gray-300' : 'text-gray-700'
                      }`}>
                        {book.description}
                      </p>
                      
                      <div className="flex justify-between items-center mt-3">
                        <span className={`text-xs ${
                          theme === 'dark' ? 'text-gray-500' : 'text-gray-400'
                        }`}>
                          Added: {new Date(book.addedDate).toLocaleDateString()}
                        </span>
                        
                        <motion.button
                          whileHover={{ scale: 1.1 }}
                          whileTap={{ scale: 0.95 }}
                          className={`text-xs px-3.5 py-1.5 rounded-full ${
                            theme === 'dark'
                              ? 'bg-blue-600/20 text-blue-400 hover:bg-blue-500/30'
                              : 'bg-blue-50 text-blue-600 hover:bg-blue-100'
                          } font-medium`}
                        >
                          Read
                        </motion.button>
                      </div>
                    </div>
                  </motion.div>
                ))}
              </motion.div>
            ) : (
              <motion.div
                key="no-results"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0 }}
                className={`text-center py-16 rounded-lg border ${
                  theme === 'dark' ? 'bg-gray-800/40 border-gray-700/70' : 'bg-gray-50/60 border-gray-200/70'
                } backdrop-blur-sm`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className={`h-14 w-14 mx-auto mb-4 ${
                  theme === 'dark' ? 'text-gray-600' : 'text-gray-400'
                }`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
                <h3 className={`text-xl font-medium mb-2 ${
                  theme === 'dark' ? 'text-gray-300' : 'text-gray-700'
                }`}>
                  No books found
                </h3>
                <p className={theme === 'dark' ? 'text-gray-400' : 'text-gray-500'}>
                  Try adjusting your search or filter criteria
                </p>
              </motion.div>
            )}
          </AnimatePresence>
        </>
      )}
    </div>
  );
};

export default BookListWithThumbnails; 