import React, { useState, useEffect, useRef, useCallback } from 'react';
import * as pdfjsLib from 'pdfjs-dist';
import { motion, AnimatePresence } from 'framer-motion';
import { useSwipeable } from 'react-swipeable';

// Set up PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

const PDFViewer = ({ pdfPath, fileUrl, bookTitle }) => {
  const [pdf, setPdf] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [scale, setScale] = useState(1.2);
  const [error, setError] = useState(null);
  const [pageDirection, setPageDirection] = useState(0);
  const [pageUrls, setPageUrls] = useState({});
  const [isLoading, setIsLoading] = useState(true);
  const [showPlaceholder, setShowPlaceholder] = useState(false);
  const containerRef = useRef(null);
  
  // Use either pdfPath or fileUrl 
  const effectivePath = pdfPath || fileUrl;
  
  // Function to render a page to the cache
  const renderPageToCache = async (pdfDoc, pageNum, cache) => {
    if (!pdfDoc) return null;
    
    try {
      const page = await pdfDoc.getPage(pageNum);
      const viewport = page.getViewport({ scale: 1.0 });
      
      // Create an offscreen canvas
      const canvas = document.createElement('canvas');
      canvas.height = viewport.height;
      canvas.width = viewport.width;
      
      // Render to the canvas
      const renderContext = {
        canvasContext: canvas.getContext('2d'),
        viewport: viewport
      };
      
      await page.render(renderContext).promise;
      
      // Store the rendered page as a data URL
      const pageUrl = canvas.toDataURL('image/png');
      cache[pageNum] = pageUrl;
      
      return pageUrl;
    } catch (err) {
      console.error(`Error rendering page ${pageNum}:`, err);
      return null;
    }
  };
  
  // Change page function wrapped in useCallback to prevent re-creation on every render
  const changePage = useCallback((delta) => {
    if (!pdf) return;
    
    // Make sure we stay within bounds
    const newPage = Math.max(1, Math.min(currentPage + delta, totalPages));
    
    // If already at the target page, do nothing
    if (newPage === currentPage) return;
    
    // Set the direction for animation
    setPageDirection(delta > 0 ? 1 : -1);
    
    // Change page
    setCurrentPage(newPage);
  }, [currentPage, pdf, totalPages]);
  
  // Change zoom level
  const changeZoom = (delta) => {
    const newScale = Math.max(0.5, Math.min(scale + delta, 3));
    setScale(newScale);
  };
  
  // Page flip animation variants
  const pageVariants = {
    enter: (direction) => ({
      x: direction > 0 ? "100%" : "-100%",
      opacity: 0,
      rotateY: direction > 0 ? -20 : 20,
      boxShadow: "0px 0px 0px rgba(0, 0, 0, 0.2)"
    }),
    center: {
      x: 0,
      opacity: 1,
      rotateY: 0,
      boxShadow: "0px 10px 30px rgba(0, 0, 0, 0.3)"
    },
    exit: (direction) => ({
      x: direction < 0 ? "100%" : "-100%",
      opacity: 0,
      rotateY: direction < 0 ? -20 : 20,
      boxShadow: "0px 0px 0px rgba(0, 0, 0, 0.2)"
    })
  };
  
  // Handle swipe gestures
  const swipeHandlers = useSwipeable({
    onSwipedLeft: () => changePage(1),
    onSwipedRight: () => changePage(-1),
    preventDefaultTouchmoveEvent: true,
    trackMouse: false,
    trackTouch: true,
    delta: 10, // Lower threshold for swipe detection
    swipeDuration: 500, // Allow slower swipes
  });

  // Handle keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === 'ArrowRight') {
        changePage(1);
      } else if (e.key === 'ArrowLeft') {
        changePage(-1);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [changePage]);
  
  // Resize handling for responsiveness
  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        const containerWidth = containerRef.current.clientWidth;
        const containerHeight = containerRef.current.clientHeight;
        // More responsive scaling based on both dimensions
        const isMobile = window.innerWidth < 768;
        // Use larger scale on desktop for better readability
        const newScale = isMobile 
          ? Math.min(0.9, (containerWidth / 600) * 0.9, (containerHeight / 800) * 0.9) 
          : Math.min(1.5, containerWidth / 600);
        setScale(newScale);
      }
    };
    
    handleResize(); // Call once to initialize
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Add touch gesture handling for pinch zoom
  useEffect(() => {
    if (!containerRef.current) return;
    
    let initialDistance = 0;
    let initialScale = scale;
    
    const handleTouchStart = (e) => {
      if (e.touches.length === 2) {
        // Get initial distance between two fingers
        initialDistance = Math.hypot(
          e.touches[0].clientX - e.touches[1].clientX,
          e.touches[0].clientY - e.touches[1].clientY
        );
        initialScale = scale;
      }
    };
    
    const handleTouchMove = (e) => {
      if (e.touches.length === 2) {
        // Calculate new distance
        const newDistance = Math.hypot(
          e.touches[0].clientX - e.touches[1].clientX,
          e.touches[0].clientY - e.touches[1].clientY
        );
        
        // Calculate scale factor based on distance change
        const scaleFactor = newDistance / initialDistance;
        const newScale = Math.max(0.5, Math.min(3, initialScale * scaleFactor));
        
        setScale(newScale);
        e.preventDefault(); // Prevent default pinch zoom
      }
    };
    
    const container = containerRef.current;
    container.addEventListener('touchstart', handleTouchStart, { passive: false });
    container.addEventListener('touchmove', handleTouchMove, { passive: false });
    
    return () => {
      container.removeEventListener('touchstart', handleTouchStart);
      container.removeEventListener('touchmove', handleTouchMove);
    };
  }, [scale]);

  // Update the document title with the book title
  useEffect(() => {
    if (bookTitle) {
      document.title = `Reading: ${bookTitle}`;
      
      return () => {
        document.title = 'Track Your Study';
      };
    }
  }, [bookTitle]);

  // Load the PDF document - simplified version without URL fixing
  useEffect(() => {
    let loadingTask = null;
    let isMounted = true;
    let abortController = new AbortController();
    
    async function loadPDF() {
      try {
        setError(null);
        setIsLoading(true);
        setShowPlaceholder(false);
        
        // Handle case when effectivePath is not provided
        if (!effectivePath) {
          if (isMounted) {
            setShowPlaceholder(true);
            setError("No PDF document specified");
            setIsLoading(false);
          }
          return;
        }
        
        console.log("Loading PDF from path:", effectivePath);
        
        // Load the PDF document directly with minimal options
        loadingTask = pdfjsLib.getDocument({
          url: effectivePath,
          // Use minimal options to reduce potential issues
          cMapUrl: 'https://cdn.jsdelivr.net/npm/pdfjs-dist@2.16.105/cmaps/',
          cMapPacked: true
        });
        
        // Track loading progress
        loadingTask.onProgress = (progress) => {
          if (isMounted) {
            const percent = Math.round(progress.loaded / (progress.total || 1) * 100);
            console.log(`PDF loading progress: ${percent}%`);
          }
        };
        
        const loadedPdf = await loadingTask.promise;
        console.log("PDF loaded successfully with", loadedPdf.numPages, "pages");
        
        if (!isMounted) return;
        
        setPdf(loadedPdf);
        setTotalPages(loadedPdf.numPages);
        setCurrentPage(1);
        
        // Pre-render first page
        if (loadedPdf.numPages > 0) {
          const pageCache = {};
          
          try {
            const page1Url = await renderPageToCache(loadedPdf, 1, pageCache);
            console.log("First page rendered:", !!page1Url);
            
            if (isMounted) {
              setPageUrls(pageCache);
              setIsLoading(false);
            }
          } catch (err) {
            console.error("Error rendering page:", err);
            if (isMounted) {
              setError("Error rendering PDF page: " + err.message);
              setIsLoading(false);
            }
          }
        } else {
          setIsLoading(false);
          setError("PDF has no pages");
        }
      } catch (err) {
        if (isMounted) {
          console.error('Error loading PDF:', err);
          setError(`PDF could not be loaded: ${err.message}`);
          setIsLoading(false);
        }
      }
    }
    
    loadPDF();
    
    return () => {
      isMounted = false;
      abortController.abort();
      
      if (loadingTask && loadingTask.destroy) {
        try {
          loadingTask.destroy();
        } catch (err) {
          console.error('Error destroying PDF task:', err);
        }
      }
    };
  }, [effectivePath]);
  
  // Preload the next page when needed
  useEffect(() => {
    if (!pdf || !currentPage) return;
    
    async function preloadAdjacentPages() {
      // Preload next page if it exists
      if (currentPage < totalPages && !pageUrls[currentPage + 1]) {
        await renderPageToCache(pdf, currentPage + 1, pageUrls);
        setPageUrls({...pageUrls});
      }
      
      // Preload previous page if it exists
      if (currentPage > 1 && !pageUrls[currentPage - 1]) {
        await renderPageToCache(pdf, currentPage - 1, pageUrls);
        setPageUrls({...pageUrls});
      }
    }
    
    preloadAdjacentPages();
  }, [currentPage, pdf, pageUrls, totalPages]);

  // Clean up and reset state when path changes
  useEffect(() => {
    // Reset state when path changes
    setCurrentPage(1);
    setPageUrls({});
    setError(null);
    setShowPlaceholder(false);
    
    return () => {
      // Clean up any resources when component unmounts
      console.log("PDFViewer cleanup for path:", effectivePath);
    };
  }, [effectivePath]);

  // Return render with full-screen layout
  return (
    <div 
      className="pdf-viewer-container flex flex-col h-screen w-full"
      ref={containerRef}
      {...swipeHandlers}
      style={{ 
        height: "100vh", // Use full viewport height
        width: "100%",
        overflow: "hidden",
        display: "flex",
        flexDirection: "column"
      }}
    >
      {/* PDF page display */}
      <div className="flex-grow relative flex justify-center items-center overflow-hidden">
        {/* Loading indicator */}
        {isLoading && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-900/70 backdrop-blur-sm z-20">
            <div className="w-16 h-16 border-t-4 border-blue-500 border-solid rounded-full animate-spin"></div>
            <p className="mt-4 text-neural-200">Loading page {currentPage}...</p>
          </div>
        )}
        
        {/* Error message */}
        {error && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-900/90 backdrop-blur-sm z-20 p-6">
            <div className="p-6 max-w-md glass-panel rounded-xl border border-red-500/20">
              <h3 className="text-xl text-red-400 mb-3">Error Loading PDF</h3>
              <p className="text-neural-200 mb-4">{error}</p>
              <button
                className="px-4 py-2 bg-neural-800 hover:bg-neural-700 text-neural-200 rounded-lg"
                onClick={() => window.location.reload()}
              >
                Try Again
              </button>
            </div>
          </div>
        )}
        
        {/* Page display with animation */}
        <div className="relative w-full h-full flex items-center justify-center">
          <AnimatePresence initial={false} custom={pageDirection}>
            <motion.div
              key={currentPage}
              custom={pageDirection}
              variants={pageVariants}
              initial="enter"
              animate="center"
              exit="exit"
              transition={{ type: "spring", stiffness: 300, damping: 30 }}
              className="absolute max-w-full max-h-full flex items-center justify-center perspective-1000"
              style={{ 
                transformStyle: "preserve-3d",
                width: "100%",
                height: "100%"
              }}
            >
              {pageUrls[currentPage] ? (
                <img 
                  src={pageUrls[currentPage]} 
                  alt={`Page ${currentPage}`} 
                  className="shadow-2xl rounded"
                  style={{ 
                    maxWidth: "100%", 
                    maxHeight: "100%", 
                    objectFit: "contain",
                    transform: `scale(${scale})`,
                    transition: "transform 0.3s ease"
                  }} 
                />
              ) : showPlaceholder ? (
                <div className="w-full max-w-2xl aspect-[2/3] bg-gray-800 rounded-lg flex items-center justify-center">
                  <p className="text-gray-400">PDF document not available</p>
                </div>
              ) : null}
            </motion.div>
          </AnimatePresence>
        </div>
      </div>
      
      {/* Controls */}
      <div className="p-4 flex justify-between items-center bg-gray-900/80 backdrop-blur-sm mt-auto">
        <div className="flex items-center space-x-4">
          <button 
            onClick={() => changeZoom(-0.1)} 
            className="w-10 h-10 flex items-center justify-center rounded-full bg-neural-800 hover:bg-neural-700 text-neural-200"
            disabled={scale <= 0.5}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M5 10a1 1 0 011-1h8a1 1 0 110 2H6a1 1 0 01-1-1z" clipRule="evenodd" />
            </svg>
          </button>
          
          <span className="text-neural-200">{Math.round(scale * 100)}%</span>
          
          <button 
            onClick={() => changeZoom(0.1)} 
            className="w-10 h-10 flex items-center justify-center rounded-full bg-neural-800 hover:bg-neural-700 text-neural-200"
            disabled={scale >= 3}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M10 5a1 1 0 011 1v3h3a1 1 0 110 2h-3v3a1 1 0 11-2 0v-3H6a1 1 0 110-2h3V6a1 1 0 011-1z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
        
        <div className="text-neural-200">
          Page {currentPage} of {totalPages}
        </div>
        
        <div className="flex items-center space-x-4">
          <button 
            onClick={() => changePage(-1)} 
            className="w-10 h-10 flex items-center justify-center rounded-full bg-neural-800 hover:bg-neural-700 text-neural-200"
            disabled={currentPage <= 1}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" />
            </svg>
          </button>
          
          <button 
            onClick={() => changePage(1)} 
            className="w-10 h-10 flex items-center justify-center rounded-full bg-neural-800 hover:bg-neural-700 text-neural-200"
            disabled={currentPage >= totalPages}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

export default PDFViewer; 